from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PLAYER=ROOT/"player"
(PLAYER/"src"/"renderer.js").write_text('import * as THREE from "three";\n\nexport class VoxelRenderer {\n  constructor(container) {\n    this.container = container;\n    this.scene = new THREE.Scene();\n    this.scene.background = new THREE.Color(0x060a10);\n    this.camera = new THREE.PerspectiveCamera(50, 1, 0.01, 100);\n    this.group = new THREE.Group();\n    this.scene.add(this.group);\n\n    this.renderer = new THREE.WebGLRenderer({ antialias: true });\n    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n    container.appendChild(this.renderer.domElement);\n\n    this.yaw = 0;\n    this.pitch = 0;\n    this.distance = 4.5;\n    this.target = new THREE.Vector3(0, 1.05, 0);\n    this.drag = false;\n\n    container.addEventListener("pointerdown", e => {\n      this.drag = true; this.lx = e.clientX; this.ly = e.clientY;\n      container.setPointerCapture(e.pointerId);\n    });\n    container.addEventListener("pointerup", () => this.drag = false);\n    container.addEventListener("pointermove", e => {\n      if (!this.drag) return;\n      this.yaw -= (e.clientX - this.lx) * 0.008;\n      this.pitch -= (e.clientY - this.ly) * 0.006;\n      this.pitch = Math.max(-1.3, Math.min(1.3, this.pitch));\n      this.lx = e.clientX; this.ly = e.clientY;\n    });\n    container.addEventListener("wheel", e => {\n      e.preventDefault();\n      this.distance *= Math.exp(e.deltaY * 0.001);\n      this.distance = Math.max(1.3, Math.min(9, this.distance));\n    }, {passive:false});\n\n    window.addEventListener("keydown", e => {\n      if (e.key === "0") { this.yaw = 0; this.pitch = 0; this.distance = 4.5; }\n    });\n    window.addEventListener("resize", () => this.resize());\n    this.resize();\n    this.animate();\n  }\n\n  resize() {\n    const w = Math.max(1, this.container.clientWidth);\n    const h = Math.max(1, this.container.clientHeight);\n    this.camera.aspect = w / h;\n    this.camera.updateProjectionMatrix();\n    this.renderer.setSize(w, h, false);\n  }\n\n  setFrame(voxels, header) {\n    this.group.clear();\n    const n = Math.floor(voxels.length / 6);\n    if (!n) return;\n\n    const sx = 2.5 / Math.max(header.grid_x - 1, 1);\n    const sy = 2.5 / Math.max(header.grid_y - 1, 1);\n    const sz = 2.25 / Math.max(header.grid_z - 1, 1);\n    const size = Math.max(0.025, Math.min(sx, sy, sz) * 1.2);\n\n    const geo = new THREE.BoxGeometry(size, size, size);\n    const mat = new THREE.MeshBasicMaterial({ vertexColors: true });\n    const mesh = new THREE.InstancedMesh(geo, mat, n);\n    const dummy = new THREE.Object3D();\n    const color = new THREE.Color();\n\n    for (let i = 0; i < n; i++) {\n      const x = voxels[i*6], y = voxels[i*6+1], z = voxels[i*6+2];\n      dummy.position.set(\n        (x / Math.max(header.grid_x-1,1) - 0.5) * 2.5,\n        (z / Math.max(header.grid_z-1,1)) * 2.25,\n        (y / Math.max(header.grid_y-1,1) - 0.5) * 2.5\n      );\n      dummy.updateMatrix();\n      mesh.setMatrixAt(i, dummy.matrix);\n      color.setRGB(\n        voxels[i*6+3] / 255,\n        voxels[i*6+4] / 255,\n        voxels[i*6+5] / 255\n      );\n      mesh.setColorAt(i, color);\n    }\n\n    mesh.instanceMatrix.needsUpdate = true;\n    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;\n    this.group.add(mesh);\n  }\n\n  animate() {\n    requestAnimationFrame(() => this.animate());\n    const cp = Math.cos(this.pitch), sp = Math.sin(this.pitch);\n    const cy = Math.cos(this.yaw), sy = Math.sin(this.yaw);\n    this.camera.position.set(\n      this.target.x + this.distance * cp * sy,\n      this.target.y + this.distance * sp,\n      this.target.z + this.distance * cp * cy\n    );\n    this.camera.lookAt(this.target);\n    this.renderer.render(this.scene, this.camera);\n  }\n}\n',encoding="utf-8")
(PLAYER/"src"/"main.js").write_text('import { VoxelRenderer } from "./renderer.js";\n\nconst $ = id => document.getElementById(id);\nconst status = $("status");\nconst timeline = $("timeline");\nconst play = $("playPause");\nconst timeLabel = $("timeLabel");\nconst stats = $("stats");\n\nasync function decodeV4D() {\n  const response = await fetch("/reconstructed_color.v4d");\n  if (!response.ok) throw new Error("reconstructed_color.v4d not found");\n  const buffer = await response.arrayBuffer();\n  const dv = new DataView(buffer);\n\n  const magic = String.fromCharCode(...new Uint8Array(buffer, 0, 4));\n  if (magic !== "V4D1") throw new Error("Invalid V4D file");\n\n  let o = 4;\n  const version = dv.getUint16(o, true); o += 2;\n  if (version !== 1) throw new Error("Unsupported V4D version");\n\n  const header = {\n    grid_x: dv.getUint16(o, true),\n    grid_y: dv.getUint16(o + 2, true),\n    grid_z: dv.getUint16(o + 4, true),\n    frame_count: dv.getUint32(o + 6, true),\n    fps: dv.getFloat32(o + 10, true),\n    voxel_size: dv.getFloat32(o + 14, true)\n  };\n  o += 18;\n\n  const frames = [];\n  for (let f = 0; f < header.frame_count; f++) {\n    const timestamp = dv.getFloat32(o, true); o += 4;\n    const count = dv.getUint32(o, true); o += 4;\n    const voxels = new Uint8Array(buffer, o, count * 6);\n    o += count * 6;\n    frames.push({ timestamp, voxels });\n  }\n  return { header, frames };\n}\n\n(async () => {\n  try {\n    const data = await decodeV4D();\n    const viewer = new VoxelRenderer($("viewport"));\n\n    timeline.max = data.frames.length - 1;\n    let current = 0;\n    let playing = false;\n    let last = performance.now();\n    let accumulator = 0;\n\n    function showFrame(index) {\n      current = Math.max(0, Math.min(data.frames.length - 1, index));\n      const frame = data.frames[current];\n      viewer.setFrame(frame.voxels, data.header);\n      timeline.value = current;\n      timeLabel.textContent =\n        `${frame.timestamp.toFixed(2)} / ${data.frames.at(-1).timestamp.toFixed(2)} s`;\n      stats.textContent =\n        `Frame ${current + 1}/${data.frames.length} • ` +\n        `${Math.floor(frame.voxels.length / 6).toLocaleString()} voxels • ` +\n        `${data.header.fps.toFixed(1)} FPS`;\n    }\n\n    showFrame(0);\n    status.textContent = "4D HUMAN READY";\n\n    timeline.addEventListener("input", e => showFrame(Number(e.target.value)));\n    play.addEventListener("click", () => {\n      playing = !playing;\n      play.textContent = playing ? "Pause" : "Play";\n    });\n\n    function tick(now) {\n      const dt = now - last;\n      last = now;\n      if (playing) {\n        accumulator += dt;\n        const interval = 1000 / data.header.fps;\n        if (accumulator >= interval) {\n          const steps = Math.max(1, Math.floor(accumulator / interval));\n          accumulator = 0;\n          let next = current + steps;\n          if (next >= data.frames.length) next = 0;\n          showFrame(next);\n        }\n      }\n      requestAnimationFrame(tick);\n    }\n    requestAnimationFrame(tick);\n  } catch (error) {\n    console.error(error);\n    status.textContent = "ERROR: " + error.message;\n  }\n})();\n',encoding="utf-8")
(PLAYER/"src"/"style.css").write_text('html,body{margin:0;height:100%;background:#05080d;color:#eaf7ff;font-family:Arial,sans-serif}\n#app{height:100%;display:flex;flex-direction:column}\nheader{padding:16px 22px;display:flex;justify-content:space-between;align-items:center;background:#0b1320;border-bottom:1px solid #24354a}\nh1{margin:0;font-size:20px;color:#65e7ff}\n#status{font-size:13px;color:#8de9a9}\nmain{flex:1;min-height:0;display:flex;flex-direction:column}\n#viewport{flex:1;min-height:0}\n.controls{display:flex;gap:12px;align-items:center;padding:14px 20px;background:#0b1320}\n.controls input{flex:1}.controls button{padding:9px 18px;border:0;border-radius:8px;background:#39d5ff;color:#031018;font-weight:bold}\n.controls span,#stats,.help{font-size:13px;color:#9eb2c5}.help,#stats{padding:8px 20px;background:#08101a}\n',encoding="utf-8")
(PLAYER/"index.html").write_text('<!doctype html>\n<html>\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Voxel Replay — 4D Human</title>\n</head>\n<body>\n<div id="app">\n<header>\n  <h1>Voxel Replay — 4D Human</h1>\n  <span id="status">Loading…</span>\n</header>\n<main>\n  <div id="viewport"></div>\n  <div class="controls">\n    <button id="playPause">Play</button>\n    <input id="timeline" type="range" min="0" max="0" value="0">\n    <span id="timeLabel">0.00 / 0.00 s</span>\n  </div>\n  <div id="stats">Loading…</div>\n  <div class="help">Drag = rotate · Wheel = zoom · 0 = reset</div>\n</main>\n<script type="module" src="/src/main.js"></script>\n</div>\n</body>\n</html>\n',encoding="utf-8")
